import ABFieldJsonCore from "../../core/dataFields/ABFieldJsonCore";

export default class ABFieldJson extends ABFieldJsonCore {
   // constructor(values, object) {
   //    super(values, object);
   // }

   ///
   /// Working with Actual Object Values:
   ///

   // return the grid column header definition for this instance of ABFieldJson
   columnHeader(options) {
      const config = super.columnHeader(options);

      config.editor = "text";
      config.css = "textCell";

      // when called by ABViewFormCustom, will need a .template() fn.
      config.template = (obj) => {
         const val = obj[this.columnName];

         if (val && typeof val == "object") {
            try {
               return JSON.stringify(val);
            } catch (e) {
               return val.toString();
            }
         }

         return val || "";
      };

      config.editFormat = (val) => {
         if (val && typeof val == "object") {
            try {
               return JSON.stringify(val);
            } catch (e) {
               return val.toString();
            }
         }

         return val || "";
      };

      config.editParse = (val) => {
         if (val && typeof val == "string") {
            try {
               return JSON.parse(val);
            } catch (e) {
               /* ignore */
            }
         }

         return val;
      };

      return config;
   }

   /*
    * @funciton formComponent
    * returns a drag and droppable component that is used on the UI
    * interface builder to place form components related to this ABField.
    *
    * an ABField defines which form component is used to edit it's contents.
    * However, what is returned here, needs to be able to create an instance of
    * the component that will be stored with the ABViewForm.
    */
   formComponent() {
      // read-only for now
      const formComponentSetting = super.formComponent();

      // .common() is used to create the display in the list
      formComponentSetting.common = () => {
         return {
            key: "json",
            settings: {
               type: "string",
            },
         };
      };

      return formComponentSetting;
   }

   formComponentMobile() {
      return super.formComponent("mobile-fieldreadonly");
   }

   detailComponent() {
      const detailComponentSetting = super.detailComponent();

      detailComponentSetting.common = () => {
         return {
            key: "detailtext",
         };
      };

      return detailComponentSetting;
   }

   setValue(item, rowData) {
      let val = rowData[this.columnName];

      if (val && typeof val == "object") {
         try {
            val = JSON.stringify(val);
         } catch (e) {
            /* ignore */
         }
      }

      const cloneRow = Object.assign({}, rowData, { [this.columnName]: val });

      super.setValue(item, cloneRow);

      if (item) {
         item.config.value = val;
      }
   }

   /**
    * @method formCleanData()
    * Review the data a form is about to submit and change/remove it as
    * appropriate.
    * @param {obj} rowData
    *        The {data} a form has collected and is about to save.
    * @return {undefined}
    */
   formCleanData(rowData) {
      let val = rowData[this.columnName];
      if (val === "") {
         // "" isn't a valid json value, so just remove the data and
         // let the DB handle the default value.
         delete rowData[this.columnName];
      }
   }
};
